            while stack:
                x, y = stack.pop(); cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny)); stack.append((nx, ny))
            comps.append((color, cells))
    # A small singleton is a color key. Recolor the separated, congruent
    # counterpart of the largest same-shape motifs to that key's color.
    out = [row[:] for row in grid]
    singles = [(col, cells[0]) for col, cells in comps if len(cells) == 1]
    if not singles:
        return out
    marker_color, marker = singles[0]
    for color, cells in comps:
        if color == marker_color or len(cells) < 2:
            continue
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        shape = frozenset((r-min(rs),c-min(cs)) for r,c in cells)
        for other_color, other in comps:
            if other is cells or other_color == color or len(other) != len(cells):
                continue
            ors = [r for r,c in other]; ocs = [c for r,c in other]
            other_shape = frozenset((r-min(ors),c-min(ocs)) for r,c in other)
            if shape != other_shape:
