            inside = min(rs) <= marker[0] <= max(rs) and min(cs) <= marker[1] <= max(cs)
            other_inside = min(ors) <= marker[0] <= max(ors) and min(ocs) <= marker[1] <= max(ocs)
            if inside != other_inside:
                target = other if inside else cells
                for r,c in target:
                    out[r][c] = marker_color
                return out
    # Fallback for a pointer aligned with a small repeated object: shoot along
    # the cardinal axis through the marker and recolor the first object hit.
    mr, mc = marker
    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
        r,c = mr+dr,mc+dc
        while 0 <= r < h and 0 <= c < w:
            if grid[r][c] != bg:
                target_color = grid[r][c]
                target = next((cells for col,cells in comps if col == target_color and (r,c) in cells), None)
