    c0 = min(c for r, c in points)
    return frozenset((r-r0, c-c0) for r, c in points)


def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            points = []
            while stack:
                x, y = stack.pop()
                points.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny)); stack.append((nx, ny))
            components.append((color, points))

    markers = []
    for color, points in components:
        rs = [r for r, c in points]
        cs = [c for r, c in points]
        bh, bw = max(rs)-min(rs)+1, max(cs)-min(cs)+1
        if len(points) >= 7 and bh >= 4 and bw >= 4 and bh*bw > len(points)*2:
            markers.append((color, points))
    if not markers:
        return [row[:] for row in grid]
    marker_color, marker = max(markers, key=lambda x: len(x[1]))
    r0, r1 = min(r for r,c in marker), max(r for r,c in marker)
    c0, c1 = min(c for r,c in marker), max(c for r,c in marker)
    inside, outside = [], []
    for color, points in components:
        if color == marker_color:
            continue
        in_box = all(r0 <= r <= r1 and c0 <= c <= c1 for r,c in points)
        item = (color, points, _normalize(points))
        (inside if in_box else outside).append(item)
    pairs = []
    for ci, pi, si in inside:
        for co, po, so in outside:
            if si == so:
                pairs.append((len(pi), co, pi))
    if not pairs:
        return [row[:] for row in grid]
    _, target_color, target = max(pairs, key=lambda item: item[0])
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = target_color
    return out

