    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append((color, cells))
    # Find the prominent L-shaped pointer. From its arm endpoints, cast rays
    # through background; the first separate object touched adopts its color.
    pointers = []
    for color, cells in components:
        cellset = set(cells)
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        bh, bw = r1-r0+1, c1-c0+1
        if bh < 3 or bw < 3 or len(cells) < bh + bw - 1:
            continue
        if len(cells) > bh + bw + 2:
            continue
        corners = sum((r, c) in cellset for r in (r0, r1) for c in (c0, c1))
        if corners < 3:
            continue
        pointers.append((len(cells), color, cells, cellset))
    if not pointers:
        return [row[:] for row in grid]
    _, pointer_color, points, pointset = max(pointers)
    rays = []
    for r, c in points:
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r+dr, c+dc
            if (nr, nc) in pointset:
                continue
            # Rays begin at boundary cells of the pointer and continue outward.
            rays.append((r, c, dr, dc))
    for r, c, dr, dc in rays:
        x, y = r+dr, c+dc
        while 0 <= x < h and 0 <= y < w and grid[x][y] == background:
            x += dr
            y += dc
        if 0 <= x < h and 0 <= y < w and grid[x][y] != pointer_color:
            target_color = grid[x][y]
            target = next((cells for color, cells in components if color == target_color and (x, y) in cells), None)
            if target:
                out = [row[:] for row in grid]
